//! Transport, authentication, typed failures, cursor pagination and MCP tool calls shared by every component client. Generated by scripts/sdks/rust.py from contracts/http; do not edit.
use reqwest::Method;
use serde::de::DeserializeOwned;
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use std::fmt;
use std::future::Future;
use std::sync::atomic::{AtomicU64, Ordering};

/// Both credentials are sent as `Authorization: Bearer`; the server tells them apart.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Auth {
    /// A personal merchant session from `identity().post_auth_login` or `post_auth_register`.
    PersonalSession(String),
    /// A scoped integration key from `identity().post_workspace_integrations`. Keep it server-side.
    IntegrationKey(String),
}

/// Failure kinds of the shared error envelope (components/core/src/failure.rs).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ProblemKind {
    /// `validation_error`
    ValidationError,
    /// `authentication_required`
    AuthenticationRequired,
    /// `permission_denied`
    PermissionDenied,
    /// `not_found`
    NotFound,
    /// `conflict`
    Conflict,
    /// `quota_exceeded`
    QuotaExceeded,
    /// `rate_limited`
    RateLimited,
    /// `temporarily_unavailable`
    TemporarilyUnavailable,
    /// `provider_unavailable`
    ProviderUnavailable,
    /// `internal_error`
    InternalError,
    /// `revision_conflict`
    RevisionConflict,
    /// `output_contract_error`
    OutputContractError,
    /// A kind added by a newer server.
    #[serde(other)]
    Unknown,
}

/// One entry of the `{"errors":[...]}` envelope every HTTP failure and MCP tool error carries.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Problem {
    /// `kind`
    pub kind: ProblemKind,
    /// `retryable`
    pub retryable: bool,
    /// `scope`
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub scope: Option<String>,
    /// `pointer`
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pointer: Option<String>,
    /// `currentRevision`
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub current_revision: Option<i64>,
    /// `code`
    pub code: String,
    /// `status`
    pub status: i64,
    /// `detail`
    pub detail: String,
}

/// An HTTP failure or MCP tool error with the server's structured problems.
#[derive(Clone, Debug)]
pub struct ApiError {
    /// HTTP status (for a tool error: the first problem's status).
    pub status: u16,
    /// Structured problems; empty when the body was not the error envelope.
    pub problems: Vec<Problem>,
    /// The complete response body.
    pub body: Value,
}

impl ApiError {
    /// The first problem's kind.
    pub fn kind(&self) -> Option<&ProblemKind> {
        self.problems.first().map(|problem| &problem.kind)
    }
    /// Whether the server says repeating the same request can succeed.
    pub fn retryable(&self) -> bool {
        self.problems.iter().any(|problem| problem.retryable)
    }
}

/// Every way a call can fail.
#[derive(Debug)]
pub enum Error {
    /// The server answered with a failure envelope.
    Api(ApiError),
    /// `/mcp` answered with a JSON-RPC protocol error (unknown tool, malformed call).
    Mcp {
        /// JSON-RPC error code.
        code: i64,
        /// Error message.
        message: String,
    },
    /// The request could not be sent or the response not read.
    Http(reqwest::Error),
    /// A response did not match the expected type.
    Decode(String),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Api(error) => match error.problems.first() {
                Some(problem) => write!(f, "HTTP {}: {}", error.status, problem.detail),
                None => write!(f, "HTTP {}", error.status),
            },
            Self::Mcp { code, message } => write!(f, "MCP error {code}: {message}"),
            Self::Http(error) => write!(f, "{error}"),
            Self::Decode(message) => write!(f, "{message}"),
        }
    }
}

impl std::error::Error for Error {}

impl From<reqwest::Error> for Error {
    fn from(error: reqwest::Error) -> Self {
        Self::Http(error)
    }
}

fn problems(body: &Value) -> Vec<Problem> {
    body.get("errors")
        .and_then(|errors| serde_json::from_value(errors.clone()).ok())
        .unwrap_or_default()
}

/// Shop, channel, context and credential for every call of one client.
#[derive(Clone, Debug, Default)]
pub struct ClientOptions {
    /// Origin of the Veyndo server, for example `https://api.veyndo.ai`.
    pub base_url: String,
    /// Credential sent as a bearer token.
    pub auth: Option<Auth>,
    /// Shop ID sent as `x-tenant`.
    pub tenant: Option<String>,
    /// Sales channel sent as `sw-sales-channel-id`.
    pub sales_channel: Option<String>,
    /// Storefront cart/customer context sent as `sw-context-token`.
    pub context_token: Option<String>,
    /// Additional headers.
    pub headers: Vec<(String, String)>,
}

/// Body, query and headers of one request.
#[derive(Clone, Debug, Default)]
pub struct RequestOptions {
    /// JSON body.
    pub body: Option<Value>,
    /// Query parameters.
    pub query: Vec<(String, String)>,
    /// Additional headers.
    pub headers: Vec<(String, String)>,
}

impl RequestOptions {
    /// Options with a JSON body.
    pub fn json(body: Value) -> Self {
        Self {
            body: Some(body),
            ..Self::default()
        }
    }
}

/// Calls Veyndo over HTTP and MCP with one shop, channel and credential.
#[derive(Debug)]
pub struct Client {
    http: reqwest::Client,
    options: ClientOptions,
    ids: AtomicU64,
}

fn encode(value: &str, keep_slash: bool) -> String {
    let mut out = String::new();
    for byte in value.bytes() {
        if byte.is_ascii_alphanumeric() || b"-._~".contains(&byte) || keep_slash && byte == b'/' {
            out.push(char::from(byte));
        } else {
            out.push_str(&format!("%{byte:02X}"));
        }
    }
    out
}

fn expand(path: &str, params: &[(&str, &str)]) -> Result<String, Error> {
    let mut out = path.to_string();
    for (name, value) in params {
        out = out
            .replace(&format!("{{*{name}}}"), &encode(value, true))
            .replace(&format!("{{{name}}}"), &encode(value, false));
    }
    if out.contains('{') {
        return Err(Error::Decode(format!("Missing path parameter in {out}")));
    }
    Ok(out)
}

impl Client {
    /// A client for these options.
    pub fn new(options: ClientOptions) -> Self {
        Self {
            http: reqwest::Client::new(),
            options,
            ids: AtomicU64::new(0),
        }
    }
    /// The options of this client.
    pub fn options(&self) -> &ClientOptions {
        &self.options
    }
    /// A client with changed options, for example another credential or cart context.
    pub fn with(&self, change: impl FnOnce(&mut ClientOptions)) -> Self {
        let mut options = self.options.clone();
        change(&mut options);
        Self {
            http: self.http.clone(),
            options,
            ids: AtomicU64::new(0),
        }
    }
    /// Sends one request and returns its JSON body, or the failure envelope as `Error::Api`.
    pub async fn request(
        &self,
        method: Method,
        path: &str,
        params: &[(&str, &str)],
        options: RequestOptions,
    ) -> Result<Value, Error> {
        let url = format!(
            "{}{}",
            self.options.base_url.trim_end_matches('/'),
            expand(path, params)?
        );
        let mut request = self
            .http
            .request(method, url)
            .header("accept", "application/json");
        if let Some(auth) = &self.options.auth {
            let (Auth::PersonalSession(secret) | Auth::IntegrationKey(secret)) = auth;
            request = request.bearer_auth(secret);
        }
        for (name, value) in [
            ("x-tenant", &self.options.tenant),
            ("sw-sales-channel-id", &self.options.sales_channel),
            ("sw-context-token", &self.options.context_token),
        ] {
            if let Some(value) = value {
                request = request.header(name, value);
            }
        }
        for (name, value) in self.options.headers.iter().chain(&options.headers) {
            request = request.header(name, value);
        }
        if !options.query.is_empty() {
            request = request.query(&options.query);
        }
        if let Some(body) = &options.body {
            request = request.json(body);
        }
        let response = request.send().await?;
        let status = response.status().as_u16();
        let json = response
            .headers()
            .get("content-type")
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.contains("json"));
        let text = response.text().await?;
        let body = if text.is_empty() {
            Value::Null
        } else if json {
            serde_json::from_str(&text).map_err(|error| Error::Decode(error.to_string()))?
        } else {
            Value::String(text)
        };
        if status >= 400 {
            return Err(Error::Api(ApiError {
                status,
                problems: problems(&body),
                body,
            }));
        }
        Ok(body)
    }
    /// JSON-RPC 2.0 calls to `POST /mcp`.
    pub fn mcp(&self) -> Mcp<'_> {
        Mcp { client: self }
    }
}

/// A native MCP tool input; `call` returns its declared output type.
pub trait Tool: Serialize {
    /// The tool name, for example `catalog.search`.
    const NAME: &'static str;
    /// The declared output, or any JSON.
    type Output: DeserializeOwned;
}

/// JSON-RPC 2.0 calls to `POST /mcp` with the client's shop and credential.
#[derive(Debug)]
pub struct Mcp<'a> {
    client: &'a Client,
}

impl Mcp<'_> {
    /// One JSON-RPC request; a protocol error becomes `Error::Mcp`.
    pub async fn rpc(&self, method: &str, params: Option<Value>) -> Result<Value, Error> {
        let id = self.client.ids.fetch_add(1, Ordering::Relaxed) + 1;
        let mut message = json!({"jsonrpc": "2.0", "id": id, "method": method});
        if let Some(params) = params {
            message["params"] = params;
        }
        let reply = self
            .client
            .request(Method::POST, "/mcp", &[], RequestOptions::json(message))
            .await?;
        if let Some(error) = reply.get("error") {
            return Err(Error::Mcp {
                code: error["code"].as_i64().unwrap_or_default(),
                message: error["message"].as_str().unwrap_or_default().to_string(),
            });
        }
        Ok(reply.get("result").cloned().unwrap_or(Value::Null))
    }
    /// The tools the current credential may call in the selected shop.
    pub async fn list_tools(&self) -> Result<Vec<Value>, Error> {
        let result = self.rpc("tools/list", None).await?;
        Ok(result["tools"].as_array().cloned().unwrap_or_default())
    }
    /// Calls a tool by name; a tool error becomes `Error::Api` with its structured problems.
    pub async fn call_raw(&self, name: &str, arguments: Value) -> Result<Value, Error> {
        let result = self
            .rpc(
                "tools/call",
                Some(json!({"name": name, "arguments": arguments})),
            )
            .await?;
        if result["isError"].as_bool() == Some(true) {
            let problems = problems(&result["structuredContent"]);
            let status = problems.first().map_or(400, |problem| problem.status);
            return Err(Error::Api(ApiError {
                status: u16::try_from(status).unwrap_or(400),
                problems,
                body: result,
            }));
        }
        Ok(result.get("structuredContent").cloned().unwrap_or(result))
    }
    /// Calls a typed tool input and decodes its output.
    pub async fn call<T: Tool>(&self, input: &T) -> Result<T::Output, Error> {
        let arguments =
            serde_json::to_value(input).map_err(|error| Error::Decode(error.to_string()))?;
        let value = self.call_raw(T::NAME, arguments).await?;
        serde_json::from_value(value).map_err(|error| Error::Decode(error.to_string()))
    }
}

/// Collects every item of a cursor-paginated read.
///
/// `fetch` receives the previous page's `nextCursor` (`None` first) and passes it as the route's
/// cursor field (`after` for catalogue, product and customer lists). Stops when `nextCursor` is
/// absent or `hasMore` is false, or after `max_pages`.
pub async fn collect_pages<F, Fut>(
    mut fetch: F,
    items: &str,
    max_pages: usize,
) -> Result<Vec<Value>, Error>
where
    F: FnMut(Option<String>) -> Fut,
    Fut: Future<Output = Result<Value, Error>>,
{
    let mut all = Vec::new();
    let mut cursor = None;
    for _ in 0..max_pages {
        let page = fetch(cursor.take()).await?;
        all.extend(page[items].as_array().cloned().unwrap_or_default());
        cursor = match &page["nextCursor"] {
            Value::String(next) => Some(next.clone()),
            Value::Number(next) => Some(next.to_string()),
            _ => None,
        };
        if cursor.is_none() || page["hasMore"] == Value::Bool(false) {
            break;
        }
    }
    Ok(all)
}
